rtl:
always_ff @(posedge clk or posedge clr)
  if (clr) gnt <= 4'h0;
  else     gnt <= next_gnt;  // clr is async — metastability risk

fix_replacement:
// Synchronize clr into clk domain first
always_ff @(posedge clk) begin
  clr_q1 <= clr;
  clr_q2 <= clr_q1;
end
always_ff @(posedge clk)
  if (clr_q2) gnt <= 4'h0;
  else        gnt <= next_gnt;
